const KEYS_OK = {"16h4cs8": "«A» senza acca è una preposizione: vado a casa.", "1f9tb7l": "«Ha» con l'acca è il verbo avere.", "1260tec": "Cuore si scrive con la c, come cuoco.", "12485wh": "Acqua si scrive con «cq».", "1kxygw3": "Scienza si scrive con la i: scie.", "kywiz5": "Dopo gn di solito non serve la i.", "1rhe9tc": "Famiglia si scrive con «gli»."};
const NEWQ = {"eng": [{"q": "Che cosa vuol dire «It's windy»?", "o": ["C'è vento", "Fa caldo", "C'è la nebbia"], "a": 0, "e": "Da «wind», vento, si aggiunge -y e nasce windy. Pensa a un aquilone che vola alto nel cielo!", "k": "«Windy» vuol dire ventoso: it's windy, c'è vento."}, {"q": "Come si dice «Fa freddo» in inglese?", "o": ["It's cold", "It's hot", "It's warm"], "a": 0, "e": "Il contrario di cold è hot, caldo. D'inverno: It's cold, put on your coat! Fa freddo, mettiti il cappotto!", "k": "«Cold» vuol dire freddo: It's cold, fa freddo."}, {"q": "Che cosa vuol dire «It's foggy»?", "o": ["C'è il sole", "C'è la nebbia", "Sta nevicando"], "a": 1, "e": "Come sun-sunny e cloud-cloudy: fog diventa foggy, raddoppiando la g. Con la nebbia si vede pochissimo!", "k": "«Fog» è la nebbia: it's foggy, c'è la nebbia."}, {"q": "Come chiedi «Che tempo fa?» in inglese?", "o": ["Where is the weather?", "What's the weather like?", "What time is it?"], "a": 1, "e": "«Weather» è il tempo atmosferico, «time» il tempo dell'orologio. Rispondi così: It's sunny! oppure It's raining!", "k": "Che tempo fa? si dice What's the weather like?"}, {"q": "Come si dice «arcobaleno» in inglese?", "o": ["snowball", "rainbow", "sunflower"], "a": 1, "e": "Rain vuol dire pioggia e bow vuol dire arco: l'arco che appare quando ci sono insieme pioggia e sole.", "k": "L'arcobaleno si dice rainbow."}, {"q": "Che cosa vuol dire «hat»?", "o": ["giacca", "sciarpa", "cappello"], "a": 2, "e": "Hat fa rima con cat: immagina un gatto con un cappello in testa, a cat in a hat!", "k": "«Hat» vuol dire cappello."}, {"q": "Come si dice «maglione» in inglese britannico?", "o": ["jumper", "shirt", "jacket"], "a": 0, "e": "In inglese americano si dice sweater. Jacket è la giacca e shirt la camicia.", "k": "In inglese britannico il maglione si dice jumper."}, {"q": "Che cosa vuol dire «scarf»?", "o": ["cintura", "calzino", "sciarpa"], "a": 2, "e": "D'inverno metti scarf, hat e gloves: sciarpa, cappello e guanti, e il freddo non ti fa paura!", "k": "«Scarf» vuol dire sciarpa."}, {"q": "Come si dicono «calzini» in inglese?", "o": ["shorts", "socks", "boots"], "a": 1, "e": "Un calzino è a sock, due calzini socks. Shorts sono i pantaloncini e boots gli stivali.", "k": "I calzini si dicono socks."}, {"q": "Che cosa vuol dire «I'm wearing a coat»?", "o": ["Compro un cappotto", "Indosso un cappotto", "Cerco un cappotto"], "a": 1, "e": "I'm wearing a coat: sto indossando un cappotto. Con wear puoi dire tutto quello che hai addosso: I'm wearing a red hat!", "k": "«To wear» vuol dire indossare, portare addosso."}, {"q": "Come si dice «uovo» in inglese?", "o": ["leg", "ham", "egg"], "a": 2, "e": "Si dice an egg perché egg comincia con un suono vocalico, come an apple. Leg è la gamba e ham il prosciutto.", "k": "L'uovo si dice egg: an egg."}, {"q": "Che cosa vuol dire «chicken»?", "o": ["pollo", "maiale", "cucina"], "a": 0, "e": "Attenta a non confonderti: chicken è il pollo, kitchen è la cucina. Il pollo si cucina in kitchen!", "k": "«Chicken» vuol dire pollo."}, {"q": "Come si dice «succo d'arancia» in inglese?", "o": ["apple juice", "orange tea", "orange juice"], "a": 2, "e": "Juice è il succo e in inglese il frutto va prima: orange juice, apple juice, succo di mela.", "k": "Il succo d'arancia si dice orange juice."}, {"q": "Che cosa vuol dire «lunch»?", "o": ["cena", "merenda", "pranzo"], "a": 2, "e": "In ordine: breakfast la colazione, lunch il pranzo, dinner la cena. Tre pasti per tutta la giornata!", "k": "«Lunch» è il pranzo; «dinner» è la cena."}, {"q": "Che cosa vuol dire «I'm hungry»?", "o": ["Ho sonno", "Ho sete", "Ho fame"], "a": 2, "e": "Se hai sete dici I'm thirsty. Ricorda: hungry, fame per mangiare; thirsty, sete per bere.", "k": "«Hungry» vuol dire affamato: I'm hungry, ho fame."}, {"q": "Che cosa vuol dire «doctor»?", "o": ["postino", "cuoco", "medico"], "a": 2, "e": "Doctor somiglia a dottore, quindi è facile! Il medico lavora in ospedale, che in inglese si dice hospital.", "k": "«Doctor» vuol dire medico, dottore."}, {"q": "Come si dice «pompiere» in inglese?", "o": ["police officer", "farmer", "firefighter"], "a": 2, "e": "Fire è il fuoco e fighter chi combatte: chi combatte il fuoco! Si dice anche fireman.", "k": "Il pompiere si dice firefighter."}, {"q": "Chi è un «farmer»?", "o": ["il farmacista", "il fornaio", "l'agricoltore"], "a": 2, "e": "Farm è la fattoria. Attenta al trucco: il farmacista non è farmer, si dice pharmacist o chemist!", "k": "«Farmer» è l'agricoltore, che lavora in una fattoria."}, {"q": "Come si dice «cuoco» in inglese?", "o": ["baker", "driver", "cook"], "a": 2, "e": "Cook vuol dire anche cucinare: a cook cooks! Baker è il fornaio e driver l'autista.", "k": "Il cuoco si dice cook (anche chef)."}, {"q": "Che lavoro fa un «vet»?", "o": ["cura gli animali", "dipinge le case", "guida l'autobus"], "a": 0, "e": "Vet è la parola breve per veterinario, il medico degli animali. Porti il tuo cane dal vet quando sta male.", "k": "«Vet» è il veterinario, il medico degli animali."}, {"q": "Che ore sono se dici «It's quarter to nine»?", "o": ["le nove e un quarto", "le nove e mezza", "le nove meno un quarto"], "a": 2, "e": "To vuol dire «meno», past vuol dire «e». Quarter to nine: mancano 15 minuti alle nove, cioè 8:45.", "k": "«Quarter to» vuol dire meno un quarto."}, {"q": "Come si dice «Sono le quattro e dieci»?", "o": ["It's ten to four", "It's four to ten", "It's ten past four"], "a": 2, "e": "Prima i minuti, poi past, poi l'ora: ten past four. Past vuol dire «dopo»: dieci minuti dopo le quattro.", "k": "Le quattro e dieci si dice It's ten past four."}, {"q": "Che ore sono se dici «It's twenty to five»?", "o": ["le cinque meno venti", "le quattro e venti", "le cinque e venti"], "a": 0, "e": "To vuol dire che mancano dei minuti: mancano venti minuti alle cinque, cioè 4:40.", "k": "«Twenty to five» vuol dire le cinque meno venti."}, {"q": "Che cosa vuol dire «a.m.» dopo un orario, come «8 a.m.»?", "o": ["solo di sera", "tra mezzogiorno e mezzanotte", "tra mezzanotte e mezzogiorno"], "a": 2, "e": "8 a.m. sono le 8 del mattino; 8 p.m. sono le 8 di sera, cioè le 20.", "k": "a.m. indica le ore tra mezzanotte e mezzogiorno."}, {"q": "Come chiedi «A che ora pranzi?» in inglese?", "o": ["Where time do you have lunch?", "What time do you have lunch?", "How time do you have lunch?"], "a": 1, "e": "Per chiedere l'ora di qualcosa usa What time: What time do you go to school? A che ora vai a scuola?", "k": "A che ora…? si dice What time…?"}, {"q": "Come si dice «giovedì» in inglese?", "o": ["Friday", "Tuesday", "Thursday"], "a": 2, "e": "Tuesday e Thursday si somigliano: Tuesday è martedì, Thursday è giovedì. Thursday comincia con th, come thunder, tuono!", "k": "Giovedì si dice Thursday."}, {"q": "Come si dice «primo» (1°) in inglese?", "o": ["second", "one", "first"], "a": 2, "e": "One è il numero uno, first è primo in una fila o in una gara. Second è il secondo, third il terzo.", "k": "Primo si dice first, in breve 1st."}, {"q": "Come si scrive per esteso «3rd»?", "o": ["thirty", "third", "three"], "a": 1, "e": "Three è il numero 3, thirty è 30. Third è il terzo: le lettere rd sono le ultime due di third.", "k": "3rd si scrive third e vuol dire terzo."}, {"q": "Quale mese viene dopo «August»?", "o": ["September", "July", "October"], "a": 0, "e": "July, August, September: luglio, agosto, settembre. Come tutti i mesi in inglese, si scrivono con la maiuscola.", "k": "Dopo August (agosto) viene September (settembre)."}, {"q": "Come si scrive in breve «twenty-first» (ventunesimo)?", "o": ["21nd", "21th", "21st"], "a": 2, "e": "Guarda l'ultima parola: first dà st, second dà nd, third dà rd. Quindi 21st, 22nd, 23rd, ma 24th.", "k": "Twenty-first si scrive 21st, perché finisce con first."}, {"q": "Che cosa vuol dire «I get up at seven»?", "o": ["Mi alzo alle sette", "Faccio colazione alle sette", "Vado a letto alle sette"], "a": 0, "e": "Up vuol dire su: get up, tirarsi su dal letto. Il contrario è go to bed, andare a letto.", "k": "«Get up» vuol dire alzarsi dal letto."}, {"q": "Come si dice «Mi lavo i denti» in inglese?", "o": ["I brush my teeth", "I wash my face", "I brush my hair"], "a": 0, "e": "Brush è la spazzola o lo spazzolino, teeth sono i denti. Hair sono i capelli e face la faccia.", "k": "Lavarsi i denti si dice brush my teeth."}, {"q": "Come si completa: «My mum ___ to work by car»?", "o": ["going", "go", "goes"], "a": 2, "e": "Go finisce con la o, quindi si aggiunge -es: goes. Trucco: con lui, lei, esso il verbo prende la coda!", "k": "Con he, she, it si aggiunge -s: she goes."}, {"q": "Come si completa la domanda: «___ you play football?»", "o": ["Are", "Do", "Does"], "a": 1, "e": "Do you play football? Giochi a calcio? Con he, she, it invece si usa Does: Does she play football?", "k": "Con I, you, we, they la domanda comincia con Do."}, {"q": "Che cosa vuol dire «never»?", "o": ["spesso", "sempre", "mai"], "a": 2, "e": "I never eat broccoli: non mangio mai i broccoli. Always è sempre, often è spesso, sometimes è a volte.", "k": "«Never» vuol dire mai; «always» vuol dire sempre."}, {"q": "Come si completa: «There ___ three cats in the garden»?", "o": ["am", "is", "are"], "a": 2, "e": "There is a cat: c'è un gatto. There are three cats: ci sono tre gatti. Uno: is; tanti: are.", "k": "Per più cose si usa there are; per una, there is."}, {"q": "Come rispondi di no a «Is there a park near your house?»", "o": ["No, it isn't.", "No, there isn't.", "No, there aren't."], "a": 1, "e": "Si risponde con le stesse parole della domanda: Is there? No, there isn't. Isn't è la forma breve di is not.", "k": "La risposta breve negativa a Is there…? è No, there isn't."}, {"q": "Come chiedi «Sai andare in bicicletta?» in inglese?", "o": ["Can you ride a bike?", "Do you can ride a bike?", "Are you ride a bike?"], "a": 0, "e": "Basta spostare can davanti: You can ride diventa Can you ride? Rispondi Yes, I can oppure No, I can't.", "k": "Per fare la domanda, can va all'inizio: Can you…?"}, {"q": "Come rispondi di no a «Has she got a sister?»", "o": ["No, she hasn't.", "No, she isn't.", "No, she haven't."], "a": 0, "e": "Con he, she, it si usa has, quindi la risposta è hasn't, forma breve di has not.", "k": "Con she si risponde No, she hasn't."}, {"q": "Come si dice «Non ho un cane» in inglese?", "o": ["I hasn't got a dog", "I haven't got a dog", "I not have got a dog"], "a": 1, "e": "I've got a cat, but I haven't got a dog: ho un gatto ma non un cane. Hasn't va con he, she, it.", "k": "Con I si dice I haven't got, forma breve di have not."}, {"q": "Che cosa vuol dire «in front of»?", "o": ["dentro a", "davanti a", "dietro a"], "a": 1, "e": "Il contrario è behind, dietro. The car is in front of the house: la macchina è davanti alla casa.", "k": "«In front of» vuol dire davanti a."}, {"q": "Come si dice «La palla è nella scatola»?", "o": ["The ball is on the box", "The ball is in the box", "The ball is under the box"], "a": 1, "e": "In è dentro, on è sopra, under è sotto. Immagina la palla chiusa dentro la scatola: in!", "k": "«In» vuol dire dentro: in the box, nella scatola."}, {"q": "Che cosa vuol dire «between»?", "o": ["sopra", "tra, in mezzo a", "dentro"], "a": 1, "e": "I sit between Anna and Luca: sono seduta tra Anna e Luca. Pensa a un panino: il formaggio è between il pane!", "k": "«Between» vuol dire tra, in mezzo a due cose."}, {"q": "Come si dice «cugino» o «cugina» in inglese?", "o": ["uncle", "aunt", "cousin"], "a": 2, "e": "Cousin vale sia per i maschi sia per le femmine. Uncle è lo zio, aunt è la zia.", "k": "Cugino e cugina si dicono entrambi cousin."}, {"q": "Che cosa vuol dire «aunt»?", "o": ["zia", "sorella", "nonna"], "a": 0, "e": "Aunt è la zia e uncle è lo zio. Grandmother è la nonna e sister la sorella.", "k": "«Aunt» vuol dire zia."}], "geo": [{"q": "Quale di queste regioni è a statuto speciale?", "o": ["Friuli-Venezia Giulia", "Piemonte", "Toscana"], "a": 0, "e": "Le cinque sono: Valle d'Aosta, Trentino-Alto Adige, Friuli-Venezia Giulia, Sicilia e Sardegna. Trucco: tre al confine nord e due isole.", "k": "Il Friuli-Venezia Giulia è una regione a statuto speciale."}, {"q": "Quali due regioni a statuto speciale sono isole?", "o": ["Sicilia e Sardegna", "Sicilia ed Elba", "Sardegna e Corsica"], "a": 0, "e": "La Corsica è francese e l'Elba fa parte della Toscana. Le due grandi isole italiane sono anche regioni a statuto speciale.", "k": "Sicilia e Sardegna sono isole a statuto speciale."}, {"q": "Quale regione è formata da due province autonome, Trento e Bolzano?", "o": ["Veneto", "Trentino-Alto Adige", "Valle d'Aosta"], "a": 1, "e": "Il nome stesso lo dice: Trentino è la zona di Trento, Alto Adige la zona di Bolzano.", "k": "Il Trentino-Alto Adige ha le province autonome di Trento e Bolzano."}, {"q": "In quale regione molte persone parlano tedesco oltre all'italiano?", "o": ["Trentino-Alto Adige", "Liguria", "Toscana"], "a": 0, "e": "Per questo a Bolzano i cartelli stradali sono scritti in due lingue, per esempio Bolzano e Bozen.", "k": "In Alto Adige il tedesco è lingua ufficiale con l'italiano."}, {"q": "Perché alcune regioni hanno lo statuto speciale?", "o": ["Perché sono le più ricche", "Per lingue, storia o posizione particolari", "Perché hanno più abitanti"], "a": 1, "e": "Per esempio la Valle d'Aosta ha il francese, l'Alto Adige il tedesco, Sicilia e Sardegna sono isole lontane dalla penisola.", "k": "Lo statuto speciale dà più autonomia per lingue, storia o posizione."}, {"q": "Con quale unica regione italiana confina la Valle d'Aosta?", "o": ["La Liguria", "Il Piemonte", "La Lombardia"], "a": 1, "e": "Gli altri confini della Valle d'Aosta sono con due Stati: la Francia e la Svizzera.", "k": "La Valle d'Aosta confina solo con il Piemonte."}, {"q": "Quale regione si trova sulla «punta» dello stivale?", "o": ["La Campania", "La Basilicata", "La Calabria"], "a": 2, "e": "Il tacco è la Puglia, la punta è la Calabria, e davanti alla punta c'è la Sicilia, come un pallone.", "k": "La Calabria è la punta dello stivale."}, {"q": "In quale regione si trova il punto più a nord d'Italia?", "o": ["Trentino-Alto Adige", "Valle d'Aosta", "Friuli-Venezia Giulia"], "a": 0, "e": "Si chiama Vetta d'Italia, una montagna in Valle Aurina, al confine con l'Austria.", "k": "Il punto più a nord d'Italia è in Alto Adige."}, {"q": "Quale capoluogo di regione è costruito su tante isolette in una laguna?", "o": ["Genova", "Trieste", "Venezia"], "a": 2, "e": "A Venezia al posto di molte strade ci sono i canali, e ci si sposta in barca o a piedi sui ponti.", "k": "Venezia sorge su isolette nella laguna."}, {"q": "Quale capoluogo di regione si trova vicino al massiccio del Gran Sasso?", "o": ["Campobasso", "L'Aquila", "Pescara"], "a": 1, "e": "Pescara è in Abruzzo ma sul mare; il capoluogo è L'Aquila, in montagna, ai piedi del Gran Sasso.", "k": "L'Aquila, capoluogo dell'Abruzzo, è vicino al Gran Sasso."}, {"q": "In quale capoluogo di regione si trova la Mole Antonelliana?", "o": ["Torino", "Genova", "Milano"], "a": 0, "e": "È l'edificio più famoso di Torino e oggi ospita il Museo Nazionale del Cinema.", "k": "La Mole Antonelliana è il simbolo di Torino."}, {"q": "Quale capoluogo di regione ha il Duomo con la cupola del Brunelleschi?", "o": ["Perugia", "Firenze", "Bologna"], "a": 1, "e": "Filippo Brunelleschi costruì nel Quattrocento questa enorme cupola, simbolo di Firenze, capoluogo della Toscana.", "k": "La cupola del Brunelleschi è sul Duomo di Firenze."}, {"q": "Quale capoluogo di regione ha come simbolo un antico faro chiamato «la Lanterna»?", "o": ["Venezia", "Napoli", "Genova"], "a": 2, "e": "La Lanterna guida da secoli le navi che entrano nel porto di Genova, capoluogo della Liguria.", "k": "La Lanterna è il faro simbolo di Genova."}, {"q": "Quale regione è chiamata «il cuore verde d'Italia»?", "o": ["L'Umbria", "La Toscana", "Le Marche"], "a": 0, "e": "Cuore perché sta al centro della penisola, verde per i suoi boschi e le sue colline.", "k": "L'Umbria è il cuore verde d'Italia."}, {"q": "Quante regioni italiane non sono bagnate dal mare?", "o": ["8", "5", "3"], "a": 1, "e": "Sono Valle d'Aosta, Piemonte, Lombardia, Trentino-Alto Adige e Umbria: quattro al nord e una al centro.", "k": "Cinque regioni non toccano il mare."}, {"q": "Quale regione confina con la Francia ed è bagnata dal mare?", "o": ["Il Piemonte", "La Liguria", "La Valle d'Aosta"], "a": 1, "e": "Anche Piemonte e Valle d'Aosta confinano con la Francia, ma non hanno il mare. Ventimiglia è vicina al confine.", "k": "La Liguria confina con la Francia e ha il mare."}, {"q": "Quale regione italiana confina con la Slovenia?", "o": ["Il Trentino-Alto Adige", "Il Veneto", "Il Friuli-Venezia Giulia"], "a": 2, "e": "Il Friuli-Venezia Giulia è la regione più a est del nord Italia: confina con Austria e Slovenia.", "k": "Il Friuli-Venezia Giulia confina con la Slovenia."}, {"q": "Fra quali due regioni si trova la Repubblica di San Marino?", "o": ["Toscana e Umbria", "Lazio e Abruzzo", "Emilia-Romagna e Marche"], "a": 2, "e": "San Marino è un piccolo Stato indipendente sul monte Titano, vicino a Rimini, al confine fra Emilia-Romagna e Marche.", "k": "San Marino è tra Emilia-Romagna e Marche."}, {"q": "In quali enti più piccoli si dividono di solito le regioni?", "o": ["Province (o città metropolitane) e comuni", "Contee e villaggi", "Cantoni e distretti"], "a": 0, "e": "Per esempio Torino è un comune e anche una città metropolitana, dentro la regione Piemonte.", "k": "Le regioni si dividono in province e comuni."}, {"q": "Quale regione confina con Abruzzo, Lazio, Campania e Puglia?", "o": ["Il Molise", "Le Marche", "La Basilicata"], "a": 0, "e": "Il Molise è una delle regioni più piccole; si affaccia sul mare Adriatico e il suo capoluogo è Campobasso.", "k": "Il Molise confina con Abruzzo, Lazio, Campania e Puglia."}, {"q": "Che cos'è la latitudine?", "o": ["La distanza di un luogo dall'Equatore", "La distanza di un luogo dal mare", "L'altezza di un luogo sul mare"], "a": 0, "e": "Si misura sui meridiani, verso nord o verso sud. Trucco: latitudine fa salire e scendere, come una scala.", "k": "La latitudine è la distanza dall'Equatore, in gradi."}, {"q": "Che cos'è la longitudine?", "o": ["La distanza dal Polo Nord", "La lunghezza di un parallelo", "La distanza dal meridiano di Greenwich"], "a": 2, "e": "Si misura in gradi verso est o verso ovest. Trucco: longitudine va di lato, lunga come l'Equatore.", "k": "La longitudine è la distanza dal meridiano di Greenwich."}, {"q": "Da quale località passa il meridiano fondamentale, cioè 0°?", "o": ["Roma, in Italia", "Greenwich, vicino a Londra", "Parigi, in Francia"], "a": 1, "e": "A Greenwich c'è un antico osservatorio: lì è stata tracciata la linea da cui si contano tutti i meridiani.", "k": "Il meridiano 0° passa per Greenwich, vicino a Londra."}, {"q": "Qual è la latitudine dell'Equatore?", "o": ["0°", "180°", "90°"], "a": 0, "e": "Le latitudini si contano partendo dall'Equatore: lì si parte da zero, come sulla linea di partenza.", "k": "L'Equatore ha latitudine 0°."}, {"q": "Qual è la latitudine del Polo Nord?", "o": ["0°", "180° Nord", "90° Nord"], "a": 2, "e": "Dall'Equatore al polo ci sono 90 gradi, come un angolo retto: 0° all'Equatore, 90° al polo.", "k": "Il Polo Nord ha latitudine 90° Nord."}, {"q": "In quale emisfero si trova l'Italia, rispetto all'Equatore?", "o": ["Nell'emisfero sud", "Nell'emisfero nord", "Proprio sull'Equatore"], "a": 1, "e": "L'Italia è a metà strada circa tra l'Equatore e il Polo Nord, quindi nell'emisfero settentrionale.", "k": "L'Italia si trova nell'emisfero nord, o boreale."}, {"q": "Che cosa fa il settore secondario?", "o": ["Trasforma le materie prime in prodotti", "Coltiva la terra e alleva animali", "Offre servizi alle persone"], "a": 0, "e": "Per esempio il legno degli alberi diventa un tavolo in una falegnameria o in una fabbrica.", "k": "Il secondario trasforma le materie prime: industria e artigianato."}, {"q": "Che cosa offre soprattutto il settore terziario?", "o": ["Materie prime", "Prodotti di fabbrica", "Servizi"], "a": 2, "e": "Chi lavora nel terziario non produce oggetti, ma aiuta le persone: come insegnanti, autisti o commessi.", "k": "Il terziario offre servizi: scuola, negozi, trasporti, sanità."}, {"q": "Un muratore che costruisce case lavora nel settore…", "o": ["Secondario", "Terziario", "Primario"], "a": 0, "e": "Il muratore usa materiali come mattoni e cemento per creare qualcosa di nuovo: una casa.", "k": "Le costruzioni fanno parte del settore secondario."}, {"q": "Il commesso di un supermercato lavora nel settore…", "o": ["Primario", "Secondario", "Terziario"], "a": 2, "e": "Il commesso non coltiva e non fabbrica: vende prodotti già pronti, cioè offre un servizio.", "k": "Il commercio fa parte del settore terziario."}, {"q": "In quale settore lavora oggi la maggior parte degli italiani?", "o": ["Nel terziario", "Nel secondario", "Nel primario"], "a": 0, "e": "Circa sette lavoratori su dieci lavorano nei servizi. Un tempo, invece, la maggior parte lavorava nei campi.", "k": "Oggi in Italia la maggior parte delle persone lavora nel terziario."}, {"q": "Il turismo, con alberghi e guide turistiche, appartiene al settore…", "o": ["Secondario", "Primario", "Terziario"], "a": 2, "e": "Alberghi, ristoranti e guide offrono servizi a chi viaggia: per questo sono nel terziario.", "k": "Il turismo fa parte del settore terziario."}, {"q": "Quanti Paesi fanno parte oggi dell'Unione Europea?", "o": ["12", "27", "50"], "a": 1, "e": "Attenzione: 12 sono le stelle della bandiera, non i Paesi. I Paesi sono 27.", "k": "L'Unione Europea ha 27 Paesi membri."}, {"q": "In quale città furono firmati nel 1957 i trattati che fondarono la Comunità europea?", "o": ["Roma", "Bruxelles", "Berlino"], "a": 0, "e": "Sei Paesi, tra cui l'Italia, firmarono a Roma i trattati da cui è nata l'odierna Unione Europea.", "k": "Nel 1957 furono firmati i Trattati di Roma."}, {"q": "Quale Paese è uscito dall'Unione Europea nel 2020?", "o": ["Il Regno Unito", "La Spagna", "La Francia"], "a": 0, "e": "L'uscita è chiamata Brexit, da Britain, Gran Bretagna, ed exit, uscita.", "k": "Il Regno Unito è uscito dall'UE nel 2020."}, {"q": "Che cosa si festeggia il 9 maggio?", "o": ["La Festa dell'Europa", "La Festa dei lavoratori", "La Festa della Repubblica"], "a": 0, "e": "Si ricorda il 9 maggio 1950, quando Robert Schuman propose di unire i Paesi europei. La Repubblica si festeggia il 2 giugno.", "k": "Il 9 maggio è la Festa dell'Europa."}, {"q": "Qual è l'inno dell'Unione Europea?", "o": ["L'Inno alla gioia di Beethoven", "La Marsigliese", "Il Canto degli Italiani di Mameli"], "a": 0, "e": "È una musica della Nona Sinfonia di Beethoven. Il Canto degli Italiani è il nostro inno nazionale.", "k": "L'inno europeo è l'Inno alla gioia di Beethoven."}, {"q": "Quale Stato confinante con l'Italia non fa parte dell'Unione Europea?", "o": ["L'Austria", "La Svizzera", "La Francia"], "a": 1, "e": "Francia, Austria e Slovenia sono nell'Unione Europea; la Svizzera ha scelto di restarne fuori.", "k": "La Svizzera confina con l'Italia ma non è nell'UE."}, {"q": "Su una carta fisica, di che colore sono di solito le pianure?", "o": ["Giallo", "Marrone", "Verde"], "a": 2, "e": "Più si sale, più il colore cambia: verde per la pianura, giallo e arancio per le colline, marrone per i monti.", "k": "Sulle carte fisiche le pianure sono verdi."}, {"q": "Sulle carte fisiche, che cosa indica un azzurro più scuro nel mare?", "o": ["Che il mare è più freddo", "Che il mare è più profondo", "Che il mare è più salato"], "a": 1, "e": "Vicino alla costa il mare è azzurro chiaro perché è basso; al largo diventa blu scuro perché è profondo.", "k": "Azzurro più scuro vuol dire mare più profondo."}, {"q": "Che cos'è una carta tematica?", "o": ["Una carta su un solo argomento", "Una carta di tutta la Terra", "Una carta di una sola città"], "a": 0, "e": "Per esempio una carta delle coltivazioni mostra dove si coltivano riso, grano o vite.", "k": "La carta tematica mostra un argomento: clima, coltivazioni, abitanti."}, {"q": "Come si chiama la carta che mostra una città con le sue vie?", "o": ["La carta politica", "La pianta", "Il planisfero"], "a": 1, "e": "La pianta ha una scala molto grande: rimpicciolisce poco, così si vedono anche le singole strade.", "k": "La pianta mostra una città con vie e piazze."}, {"q": "Una carta che mostra pochi dettagli di una zona molto grande è a…", "o": ["Scala reale", "Grande scala", "Piccola scala"], "a": 2, "e": "Un planisfero è a piccola scala; la pianta di un quartiere è a grande scala, con tanti dettagli.", "k": "Zona grande e pochi dettagli: carta a piccola scala."}, {"q": "Che cos'è la scala grafica?", "o": ["Un segmento diviso in parti uguali", "Una freccia che indica il nord", "Un elenco dei simboli"], "a": 0, "e": "Ogni parte del segmento vale una certa distanza reale, per esempio 1 cm uguale a 10 km.", "k": "La scala grafica è un segmento che misura le distanze."}, {"q": "Sulle carte geografiche, dove si trova di solito il nord?", "o": ["A destra", "In basso", "In alto"], "a": 2, "e": "Quindi il sud è in basso, l'est a destra e l'ovest a sinistra.", "k": "Di solito sulle carte il nord è in alto."}], "ita": [{"q": "In «Al parco giocano i bambini», qual è il soggetto?", "o": ["al parco", "i bambini", "giocano"], "a": 1, "e": "Chiediti: chi gioca? I bambini! Il soggetto non sta sempre all'inizio: a volte arriva dopo il verbo.", "k": "Il soggetto può stare anche dopo il verbo."}, {"q": "In «Mi piace il gelato», qual è il soggetto?", "o": ["il gelato", "io, sottinteso", "mi"], "a": 0, "e": "È il gelato che piace a me. Prova al plurale: mi piacciono i gelati. Il verbo cambia con il soggetto!", "k": "Con «piacere», il soggetto è la cosa che piace."}, {"q": "In «Luca corre nel prato», qual è il predicato verbale?", "o": ["corre", "Luca", "nel prato"], "a": 0, "e": "Che cosa fa Luca? Corre! «Luca» è il soggetto, «nel prato» dice solo dove succede l'azione.", "k": "Il predicato verbale è il verbo che dice cosa fa il soggetto."}, {"q": "In quale frase c'è un predicato nominale?", "o": ["Il cielo è azzurro.", "Marta legge un libro.", "Il cielo si oscura."], "a": 0, "e": "«È azzurro» dice com'è il cielo: il verbo essere fa da ponte e l'aggettivo descrive. Negli altri c'è un'azione.", "k": "Predicato nominale: essere + nome o aggettivo che descrive il soggetto."}, {"q": "In «Il mio cane è in giardino», che cos'è «è»?", "o": ["un predicato verbale", "un predicato nominale", "un complemento di luogo"], "a": 0, "e": "Prova a cambiarlo: il mio cane si trova in giardino. Se «è» vuol dire «si trova», è un predicato verbale!", "k": "Essere che vuol dire «stare, trovarsi» è predicato verbale."}, {"q": "In «Marco è un pittore», «un pittore» è…", "o": ["il complemento di termine", "la parte nominale del predicato", "il complemento oggetto"], "a": 1, "e": "«È» fa da ponte e «un pittore» dice chi è Marco: insieme formano il predicato nominale.", "k": "Dopo il verbo essere, il nome è la parte nominale."}, {"q": "In quale frase c'è un complemento oggetto?", "o": ["Dormo sul divano.", "Leggo un libro.", "Vado al mare."], "a": 1, "e": "Leggo che cosa? Un libro! «Sul divano» e «al mare» hanno la preposizione: sono complementi di luogo.", "k": "Il complemento oggetto riceve l'azione, senza preposizione davanti."}, {"q": "In «Ho scritto una lettera a Paolo», qual è il complemento di termine?", "o": ["a Paolo", "ho scritto", "una lettera"], "a": 0, "e": "Ho scritto a chi? A Paolo! «Una lettera» risponde a «che cosa?»: è il complemento oggetto.", "k": "Il complemento di termine risponde a «a chi? a che cosa?»."}, {"q": "In «Il libro di storia è sul banco», «di storia» è un complemento…", "o": ["di specificazione", "di mezzo", "di termine"], "a": 0, "e": "Quale libro? Quello di storia! «Di storia» spiega meglio il nome, così non lo confondi con quello di matematica.", "k": "La specificazione precisa meglio un nome: di chi? di che cosa?"}, {"q": "In «Ci vediamo alle cinque», «alle cinque» è un complemento di…", "o": ["tempo determinato", "stato in luogo", "tempo continuato"], "a": 0, "e": "Quando ci vediamo? Alle cinque! Indica il momento preciso dell'azione, come l'ora segnata sull'orologio.", "k": "Il tempo determinato risponde a «quando?»."}, {"q": "In «Ho giocato per due ore», «per due ore» è un complemento di…", "o": ["tempo continuato", "tempo determinato", "moto per luogo"], "a": 0, "e": "Per quanto tempo ho giocato? Per due ore! Indica quanto dura l'azione: continuato, cioè che va avanti.", "k": "Il tempo continuato risponde a «per quanto tempo?»."}, {"q": "In «Passiamo per il bosco», «per il bosco» è un complemento di…", "o": ["moto per luogo", "moto da luogo", "moto a luogo"], "a": 0, "e": "Per dove passiamo? Per il bosco! Non è dove arriviamo né da dove partiamo: è la strada che attraversiamo.", "k": "Il moto per luogo indica il luogo attraverso cui si passa."}, {"q": "In «Domani vado dalla nonna», «dalla nonna» è un complemento di…", "o": ["moto a luogo", "moto da luogo", "compagnia"], "a": 0, "e": "Attenzione al «da»: vado dalla nonna vuol dire vado a casa sua. Vado verso di lei: è moto a luogo!", "k": "«Da» + persona può indicare il luogo dove si va."}, {"q": "In quale frase c'è un complemento di compagnia?", "o": ["Gioco con mia sorella.", "Taglio con le forbici.", "Parto con il treno."], "a": 0, "e": "Con chi gioco? Con mia sorella! Forbici e treno sono cose che usi: sono complementi di mezzo.", "k": "La compagnia indica con chi, persona o animale, si fa qualcosa."}, {"q": "In «Ti mando un messaggio con il telefono», «con il telefono» è un complemento di…", "o": ["termine", "mezzo", "compagnia"], "a": 1, "e": "Con che cosa mando il messaggio? Con il telefono: è lo strumento! «Ti», cioè «a te», è il complemento di termine.", "k": "Il mezzo indica lo strumento con cui si fa l'azione."}, {"q": "Quali sono i modi indefiniti del verbo?", "o": ["infinito, participio, gerundio", "indicativo, congiuntivo, condizionale", "infinito, imperativo, gerundio"], "a": 0, "e": "Si chiamano indefiniti perché non dicono chi fa l'azione: «cantare» non ha io, tu, lui. Trucco: I-P-G!", "k": "I modi indefiniti sono infinito, participio e gerundio."}, {"q": "«Che io sia» è un verbo al modo…", "o": ["congiuntivo", "indicativo", "condizionale"], "a": 0, "e": "Il congiuntivo esprime dubbi, desideri, possibilità: penso che sia tardi, spero che tu venga.", "k": "Il congiuntivo spesso si riconosce dal «che» davanti."}, {"q": "«Mangiato» è un verbo al…", "o": ["gerundio presente", "participio passato", "infinito presente"], "a": 1, "e": "Cantato, temuto, dormito sono participi passati. Con gli ausiliari formano i tempi composti: ho mangiato.", "k": "Il participio passato finisce spesso in -ato, -uto, -ito."}, {"q": "«Correre» è un verbo al modo…", "o": ["gerundio", "infinito", "imperativo"], "a": 1, "e": "È la forma che trovi nel vocabolario: correre, cantare, dormire. Non dice chi fa l'azione: è un modo indefinito.", "k": "L'infinito è il nome del verbo: finisce in -are, -ere, -ire."}, {"q": "«Io avevo mangiato» è al…", "o": ["imperfetto", "passato prossimo", "trapassato prossimo"], "a": 2, "e": "Indica un fatto successo prima di un altro fatto passato: quando sei arrivato, avevo già mangiato.", "k": "Trapassato prossimo: imperfetto dell'ausiliare + participio passato."}, {"q": "«Io avrò finito» è al…", "o": ["futuro anteriore", "passato remoto", "futuro semplice"], "a": 0, "e": "Indica un fatto futuro che avverrà prima di un altro: quando avrò finito i compiti, uscirò a giocare.", "k": "Futuro anteriore: futuro dell'ausiliare + participio passato."}, {"q": "Quale di queste forme è un tempo semplice?", "o": ["io ho letto", "io leggevo", "io avevo letto"], "a": 1, "e": "«Leggevo» è una parola sola: tempo semplice. «Ho letto» e «avevo letto» usano l'ausiliare: sono tempi composti.", "k": "I tempi semplici sono formati da una sola parola."}, {"q": "Nella forma attiva, il soggetto…", "o": ["compie l'azione", "subisce l'azione", "è sempre sottinteso"], "a": 0, "e": "Il gatto insegue il topo: il gatto fa l'azione, quindi la frase è attiva. Attivo vuol dire che fa!", "k": "Nella forma attiva il soggetto compie l'azione."}, {"q": "«Il topo è inseguito dal gatto» è in forma…", "o": ["riflessiva", "attiva", "passiva"], "a": 2, "e": "Il topo non fa nulla: subisce l'azione. Chi la compie, «dal gatto», si chiama complemento d'agente.", "k": "Nella forma passiva il soggetto subisce l'azione."}, {"q": "Come diventa al passivo «Luca lava la bici»?", "o": ["La bici è lavata da Luca.", "Luca è lavato dalla bici.", "La bici lava Luca."], "a": 0, "e": "La bici passa davanti e diventa soggetto, il verbo prende essere e Luca diventa «da Luca».", "k": "Al passivo, il complemento oggetto diventa soggetto."}, {"q": "Quali verbi possono avere la forma passiva?", "o": ["i verbi intransitivi", "i verbi transitivi", "solo i verbi ausiliari"], "a": 1, "e": "Serve un complemento oggetto che diventi soggetto: mangio la mela, la mela è mangiata. «Dormire» non ha oggetto: niente passivo!", "k": "Solo i verbi transitivi possono diventare passivi."}, {"q": "Quale ausiliare si usa nella forma passiva?", "o": ["avere", "stare", "essere"], "a": 2, "e": "La torta è preparata dalla nonna: è + preparata. A volte si usa anche venire: la torta viene preparata.", "k": "Il passivo si forma con essere + participio passato."}, {"q": "Quale ausiliare usa «mangiare» nei tempi composti?", "o": ["avere", "essere", "stare"], "a": 0, "e": "Si dice «ho mangiato», non «sono mangiato». Anche leggere, scrivere, disegnare vogliono avere: ho letto, ho scritto.", "k": "Nella forma attiva i verbi transitivi usano l'ausiliare avere."}, {"q": "In «noi cantiamo», il verbo è alla…", "o": ["prima persona singolare", "prima persona plurale", "terza persona plurale"], "a": 1, "e": "Le persone sono sei: io, tu, lui/lei al singolare; noi, voi, loro al plurale. Noi è la prima del plurale.", "k": "«Noi» è la prima persona plurale."}, {"q": "Quanti sono i tempi del modo indicativo?", "o": ["4", "6", "8"], "a": 2, "e": "Semplici: presente, imperfetto, passato remoto, futuro. Composti: passato prossimo, trapassato prossimo, trapassato remoto, futuro anteriore.", "k": "L'indicativo ha 8 tempi: 4 semplici e 4 composti."}, {"q": "«Luca è alto come Marco»: che comparativo è?", "o": ["di maggioranza", "di uguaglianza", "di minoranza"], "a": 1, "e": "Luca e Marco sono alti uguale: nessuno supera l'altro. Si può dire anche «tanto alto quanto Marco».", "k": "Il comparativo di uguaglianza usa «come» o «quanto»."}, {"q": "In «Sara è la più veloce della classe», «la più veloce» è…", "o": ["un comparativo di maggioranza", "un superlativo relativo", "un superlativo assoluto"], "a": 1, "e": "Sara è la più veloce rispetto alla classe: c'è un gruppo. «Velocissima» invece è superlativo assoluto, senza gruppo.", "k": "Il superlativo relativo indica il massimo dentro un gruppo."}, {"q": "In «una casa grande», «grande» è al grado…", "o": ["comparativo", "superlativo", "positivo"], "a": 2, "e": "Grande, piccolo, bello indicano solo una qualità. «Più grande» è comparativo, «grandissimo» è superlativo.", "k": "Il grado positivo dice la qualità senza fare confronti."}, {"q": "Qual è il comparativo di maggioranza di «buono», in una sola parola?", "o": ["ottimo", "peggiore", "migliore"], "a": 2, "e": "Si può dire «più buono» o «migliore». «Ottimo» invece è il superlativo assoluto, come «buonissimo».", "k": "Il comparativo di maggioranza di «buono» è «migliore»."}, {"q": "In «Questo è il mio zaino», «questo» è…", "o": ["un articolo determinativo", "un pronome dimostrativo", "un aggettivo dimostrativo"], "a": 1, "e": "In «questo zaino» accompagna il nome: aggettivo. In «questo è il mio zaino» sta da solo: pronome!", "k": "Se sta da solo, al posto del nome, «questo» è pronome."}, {"q": "In «Il libro che leggo è bello», «che» è…", "o": ["un articolo", "un pronome relativo", "una congiunzione"], "a": 1, "e": "Qui «che» sostituisce «il libro»: il libro è bello, io leggo il libro. Trucco: prova a dire «il quale»!", "k": "«Che» è pronome relativo quando sta al posto di un nome."}, {"q": "In «Giulia canta bene», «bene» è un avverbio di…", "o": ["tempo", "modo", "luogo"], "a": 1, "e": "Come canta Giulia? Bene! Anche male, piano e velocemente sono avverbi di modo.", "k": "Gli avverbi di modo rispondono alla domanda «come?»."}, {"q": "Quale di queste è una preposizione articolata?", "o": ["dalla", "per", "da"], "a": 0, "e": "Dalla = da + la. «Da» e «per» sono preposizioni semplici: da sole, senza articolo attaccato.", "k": "Preposizione articolata = preposizione semplice + articolo."}, {"q": "Quale congiunzione unisce due idee opposte?", "o": ["ma", "quindi", "e"], "a": 0, "e": "È tardi, ma non ho sonno: le idee vanno in direzioni diverse. «E» aggiunge, «quindi» dà una conseguenza.", "k": "«Ma» è una congiunzione che unisce idee in contrasto."}, {"q": "In «Ho tre gattini morbidi», qual è l'aggettivo qualificativo?", "o": ["tre", "morbidi", "gattini"], "a": 1, "e": "Come sono i gattini? Morbidi! «Tre» dice quanti sono: è un aggettivo numerale. «Gattini» è un nome.", "k": "L'aggettivo qualificativo dice com'è una persona o una cosa."}, {"q": "Una ricetta per preparare la pizza è un testo…", "o": ["narrativo", "regolativo", "poetico"], "a": 1, "e": "La ricetta ha ingredienti e istruzioni in ordine. Anche le regole di un gioco sono testi regolativi.", "k": "Il testo regolativo spiega come fare qualcosa, passo dopo passo."}, {"q": "In un testo argomentativo, l'opinione di chi scrive si chiama…", "o": ["morale", "titolo", "tesi"], "a": 2, "e": "Per esempio: «Leggere ogni giorno fa bene». Poi servono gli argomenti, cioè le ragioni che danno forza alla tesi.", "k": "La tesi è l'opinione che il testo argomentativo sostiene."}, {"q": "In quali parti si divide di solito un testo narrativo?", "o": ["ingredienti, procedimento, consigli", "titolo, versi, strofe", "inizio, svolgimento, conclusione"], "a": 2, "e": "All'inizio conosci personaggi e luogo, nello svolgimento succedono i fatti, nella conclusione la storia finisce.", "k": "Il testo narrativo ha inizio, svolgimento e conclusione."}, {"q": "Un buon testo informativo dà informazioni…", "o": ["vere e precise", "solo sui propri sentimenti", "inventate e fantastiche"], "a": 0, "e": "Lo trovi nei libri di scienze o nelle enciclopedie: spiega fatti reali, spesso con dati, titoli e immagini.", "k": "Il testo informativo dà notizie vere, chiare e precise."}, {"q": "Che cosa conta molto in un testo poetico?", "o": ["l'elenco dei dati numerici", "il suono e il ritmo delle parole", "l'ordine preciso delle istruzioni"], "a": 1, "e": "La poesia è scritta in versi e gioca con rime, ripetizioni e immagini per far provare emozioni.", "k": "Nel testo poetico contano suono, ritmo ed emozioni."}], "sci-corpo": [{"q": "Qual è l'ordine giusto, dal più piccolo al più grande?", "o": ["Cellula, tessuto, organo, apparato", "Organo, cellula, apparato, tessuto", "Tessuto, apparato, cellula, organo"], "a": 0, "e": "Pensa ai mattoncini: tanti mattoni fanno un muro, i muri una stanza, le stanze una casa intera.", "k": "Cellule formano tessuti, tessuti formano organi, organi formano apparati."}, {"q": "Che cos'è un tessuto del corpo?", "o": ["Un gruppo di organi che lavorano in squadra", "Una singola cellula molto grande e robusta", "Un insieme di cellule simili che fanno lo stesso lavoro"], "a": 2, "e": "Tante cellule muscolari insieme formano il tessuto muscolare, che serve a muoversi.", "k": "Un tessuto è un gruppo di cellule simili con lo stesso compito."}, {"q": "Che cos'è un apparato del corpo umano?", "o": ["Un gruppo di cellule tutte uguali", "Un solo organo molto importante", "Più organi che lavorano insieme per uno scopo"], "a": 2, "e": "Bocca, esofago, stomaco e intestino lavorano insieme: formano l'apparato digerente.", "k": "Un apparato è un gruppo di organi che collaborano."}, {"q": "Come si chiama il liquido gelatinoso che riempie la cellula?", "o": ["Il citoplasma", "Il plasma", "Il nucleo"], "a": 0, "e": "Membrana come una buccia, citoplasma come la polpa, nucleo come il nocciolo di una pesca.", "k": "Il citoplasma è la gelatina dentro la cellula."}, {"q": "Come si formano nuove cellule nel corpo?", "o": ["Una cellula si divide in due", "Nascono dal cibo appena mangiato", "Arrivano dall'aria che respiriamo"], "a": 0, "e": "Una cellula si divide in due, poi in quattro… Così cresci e ripari una sbucciatura.", "k": "Le nuove cellule nascono dalla divisione di altre cellule."}, {"q": "Come si chiama la pallina di cibo masticato che inghiottiamo?", "o": ["Il succo gastrico", "Il bolo alimentare", "Il chimo"], "a": 1, "e": "Ordine da ricordare: in bocca è bolo, nello stomaco diventa chimo.", "k": "Il cibo masticato e impastato di saliva si chiama bolo."}, {"q": "Come si chiama il movimento dei muscoli che spinge il cibo lungo l'esofago?", "o": ["La peristalsi", "La circolazione", "La respirazione"], "a": 0, "e": "È come spremere un tubetto di dentifricio: per questo il cibo scende anche a testa in giù.", "k": "La peristalsi spinge il cibo con onde di muscoli."}, {"q": "Come si chiama il cibo dopo che lo stomaco lo ha rimescolato?", "o": ["Il chimo", "Il bolo", "La bile"], "a": 0, "e": "I succhi gastrici e i muscoli dello stomaco trasformano il bolo in una poltiglia: il chimo.", "k": "Nello stomaco il cibo diventa una pappa chiamata chimo."}, {"q": "In quale piccolo sacchetto si raccoglie la bile prodotta dal fegato?", "o": ["Nel pancreas", "Nella cistifellea", "Nella milza"], "a": 1, "e": "Il fegato produce la bile, la cistifellea la conserva e la manda nell'intestino quando serve.", "k": "La bile si raccoglie nella cistifellea, sotto il fegato."}, {"q": "Come si chiama la prima parte dell'intestino tenue, dopo lo stomaco?", "o": ["Il colon", "L'esofago", "Il duodeno"], "a": 2, "e": "Nel duodeno arrivano la bile e i succhi del pancreas per continuare la digestione.", "k": "Il duodeno è il primo tratto dell'intestino tenue."}, {"q": "Come si chiamano le piccolissime sporgenze dell'intestino tenue che assorbono il nutrimento?", "o": ["I villi intestinali", "Gli alveoli", "I capillari"], "a": 0, "e": "Sono come le frange di un tappeto: tantissime, per avere più superficie che assorbe.", "k": "I villi intestinali assorbono il nutrimento e lo passano al sangue."}, {"q": "Che cosa assorbe soprattutto l'intestino crasso?", "o": ["L'ossigeno", "Il calcio delle ossa", "L'acqua"], "a": 2, "e": "Riprendendo l'acqua, rende solidi gli scarti prima che escano dal corpo.", "k": "L'intestino crasso assorbe soprattutto acqua."}, {"q": "Che cos'è la digestione?", "o": ["Masticare il cibo e basta", "Trasformare il cibo in sostanze semplici e utili", "Trasformare l'aria in ossigeno"], "a": 1, "e": "Il cibo viene spezzettato in parti piccolissime che il sangue porta a tutte le cellule.", "k": "La digestione trasforma il cibo in sostanze che il corpo usa."}, {"q": "Come si chiamano i sacchettini dei polmoni dove l'ossigeno passa nel sangue?", "o": ["Le corde vocali", "Gli alveoli polmonari", "I villi intestinali"], "a": 1, "e": "Sono come grappoli di minuscoli palloncini, avvolti da capillari sottilissimi.", "k": "Negli alveoli l'ossigeno entra nel sangue."}, {"q": "Come si chiamano i rami più sottili in cui si dividono i bronchi?", "o": ["I tendini", "I bronchioli", "Le arterie"], "a": 1, "e": "Trachea, bronchi e bronchioli sembrano un albero a testa in giù: tronco, rami, rametti.", "k": "I bronchi si dividono in rami sottili: i bronchioli."}, {"q": "Perché è meglio respirare con il naso?", "o": ["Fa respirare più in fretta", "Filtra, scalda e inumidisce l'aria", "Fa entrare meno ossigeno nel corpo"], "a": 1, "e": "Peli e muco del naso trattengono polvere e microbi, come un filtro.", "k": "Il naso pulisce, scalda e inumidisce l'aria che entra."}, {"q": "Come si chiamano i due momenti della respirazione?", "o": ["Inspirazione ed espirazione", "Contrazione e circolazione", "Digestione e assorbimento"], "a": 0, "e": "Trucco: IN-spirare, l'aria va dentro; ES-pirare, l'aria esce.", "k": "Inspiri per far entrare l'aria, espiri per farla uscire."}, {"q": "Che cosa fa il diaframma quando inspiri?", "o": ["Si abbassa e fa spazio ai polmoni", "Resta fermo e non si muove", "Si alza e schiaccia i polmoni"], "a": 0, "e": "Metti una mano sulla pancia e inspira: la senti gonfiarsi, perché il diaframma scende.", "k": "Inspirando il diaframma si abbassa e i polmoni si gonfiano."}, {"q": "Come si chiama il condotto in gola dove passano sia l'aria che il cibo?", "o": ["L'esofago", "La trachea", "La faringe"], "a": 2, "e": "Dopo la faringe le strade si dividono: l'aria va nella laringe, il cibo nell'esofago.", "k": "La faringe è la strada comune per aria e cibo."}, {"q": "Perché il polmone sinistro è un po' più piccolo del destro?", "o": ["Lascia spazio al cuore", "Serve solo quando corri", "Lavora meno del destro"], "a": 0, "e": "Il destro ha tre lobi, il sinistro due: il cuore sta un po' a sinistra.", "k": "Il polmone sinistro è più piccolo per fare posto al cuore."}, {"q": "Come si chiamano le quattro cavità del cuore?", "o": ["Due atri e due ventricoli", "Due bronchi e due alveoli", "Quattro valvole uguali"], "a": 0, "e": "Gli atri ricevono il sangue, i ventricoli, più muscolosi, lo spingono fuori.", "k": "Il cuore ha due atri sopra e due ventricoli sotto."}, {"q": "A che cosa servono le valvole del cuore?", "o": ["A pulire il sangue dai microbi", "A non far tornare indietro il sangue", "A produrre nuovo sangue"], "a": 1, "e": "Funzionano come porticine che si aprono da un solo lato. Il tum-tum è il loro chiudersi.", "k": "Le valvole fanno andare il sangue in una sola direzione."}, {"q": "Dove va il sangue nella piccola circolazione?", "o": ["Dal cuore ai polmoni e ritorno", "Dal cuore ai piedi e ritorno", "Dallo stomaco all'intestino"], "a": 0, "e": "Nei polmoni il sangue lascia l'anidride carbonica e prende ossigeno. La grande circolazione va in tutto il corpo.", "k": "Piccola circolazione: cuore, polmoni, cuore."}, {"q": "Qual è l'arteria più grande del corpo, che esce dal cuore?", "o": ["L'aorta", "La trachea", "Il femore"], "a": 0, "e": "Parte dal ventricolo sinistro e si ramifica per portare sangue ricco di ossigeno ovunque.", "k": "L'aorta è l'arteria più grande del corpo."}, {"q": "Quante volte al minuto batte più o meno il cuore di un adulto a riposo?", "o": ["Tra 60 e 100 volte", "Tra 300 e 400 volte", "Tra 5 e 10 volte"], "a": 0, "e": "Nei bambini batte un po' più veloce. Prova a contare i battiti sul polso per un minuto!", "k": "A riposo il cuore adulto batte circa 60-100 volte al minuto."}, {"q": "Come si chiama lo strumento con cui il medico ascolta il cuore?", "o": ["Il microscopio", "Lo stetoscopio", "Il termometro"], "a": 1, "e": "Ha due auricolari e un dischetto da appoggiare sul petto: amplifica i suoni del corpo.", "k": "Con lo stetoscopio il medico ascolta cuore e polmoni."}, {"q": "Quanto è grande più o meno il cuore?", "o": ["Come un pugno chiuso", "Come un chicco di riso", "Come una palla da calcio"], "a": 0, "e": "Stringi la mano: quello è circa il tuo cuore. Cresce insieme a te.", "k": "Il cuore è grande più o meno come il tuo pugno."}, {"q": "Quali sono i quattro gruppi sanguigni principali?", "o": ["A, B, AB e 0", "1, 2, 3 e 4", "A, C, D ed E"], "a": 0, "e": "Chi riceve sangue deve avere un gruppo compatibile con chi lo dona: per questo si controlla prima.", "k": "I gruppi sanguigni principali sono A, B, AB e 0."}, {"q": "Come si chiamano i muscoli che muoviamo quando vogliamo noi?", "o": ["Muscoli addormentati", "Muscoli involontari", "Muscoli volontari"], "a": 2, "e": "Braccia e gambe li comandi tu; quelli dello stomaco lavorano da soli: sono involontari.", "k": "I muscoli volontari si muovono quando decidiamo noi."}, {"q": "Di che cosa è fatto soprattutto il cuore?", "o": ["Di osso", "Di cartilagine", "Di muscolo"], "a": 2, "e": "È un muscolo involontario: batte anche mentre dormi, senza che tu ci pensi.", "k": "Il cuore è un muscolo che lavora da solo."}, {"q": "Quante paia di costole abbiamo di solito?", "o": ["12 paia", "5 paia", "30 paia"], "a": 0, "e": "Sono attaccate alle vertebre dietro e formano la gabbia toracica, come una gabbietta protettiva.", "k": "Abbiamo di solito 12 paia di costole, cioè 24."}, {"q": "Come si chiama l'osso che va dalla spalla allo sterno?", "o": ["La mandibola", "La rotula", "La clavicola"], "a": 2, "e": "La senti sotto il collo, sopra il petto: un osso lungo e sottile a forma di S.", "k": "La clavicola collega la spalla allo sterno."}, {"q": "Che cos'è un crampo?", "o": ["Un osso che si rompe", "Un nervo che si addormenta", "Un muscolo che si contrae da solo e fa male"], "a": 2, "e": "Capita spesso al polpaccio; allungare piano il muscolo di solito aiuta a farlo passare.", "k": "Il crampo è una contrazione improvvisa e dolorosa di un muscolo."}, {"q": "Che cos'è un riflesso, come togliere la mano da una cosa che scotta?", "o": ["Un sogno che fai di notte", "Una risposta veloce senza doverci pensare", "Un movimento che decidi con calma"], "a": 1, "e": "Il messaggio va al midollo spinale, che risponde subito senza aspettare il cervello.", "k": "Il riflesso è una risposta automatica e velocissima."}, {"q": "Che cosa fanno i nervi?", "o": ["Portano messaggi tra cervello e corpo", "Portano il cibo all'intestino", "Portano il sangue al cuore"], "a": 0, "e": "Sono come i fili del telefono: portano notizie al cervello e i suoi comandi ai muscoli.", "k": "I nervi portano messaggi tra il cervello e tutto il corpo."}, {"q": "La parte sinistra del cervello comanda soprattutto i movimenti di quale lato?", "o": ["Soltanto della testa", "Solo del lato sinistro", "Del lato destro del corpo"], "a": 2, "e": "I collegamenti si incrociano: l'emisfero sinistro muove la mano destra, e viceversa.", "k": "Ogni emisfero comanda soprattutto il lato opposto del corpo."}, {"q": "Quale parte del cervello controlla respiro e battito anche mentre dormi?", "o": ["Il cervelletto", "Il timpano", "Il tronco encefalico"], "a": 2, "e": "Si trova alla base del cervello, unito al midollo spinale, e lavora sempre, giorno e notte.", "k": "Il tronco encefalico controlla respiro e battito del cuore."}, {"q": "In che modo viaggiano i messaggi lungo i nervi?", "o": ["Come piccolissimi segnali elettrici", "Come bollicine d'aria", "Come gocce di sangue"], "a": 0, "e": "I segnali corrono velocissimi lungo i neuroni e passano dall'uno all'altro, come in una staffetta.", "k": "Lungo i nervi i messaggi viaggiano come piccoli segnali elettrici."}, {"q": "Come si chiamano i puntini sulla lingua che sentono i sapori?", "o": ["Le ciglia", "Le impronte digitali", "Le papille gustative"], "a": 2, "e": "Guardati la lingua allo specchio: quei puntini sono le papille, piene di cellule del gusto.", "k": "Le papille gustative della lingua sentono i sapori."}, {"q": "Quale piccola lente dentro l'occhio mette a fuoco le immagini?", "o": ["Il cristallino", "La pupilla", "Il timpano"], "a": 0, "e": "Cambia forma per vedere bene da vicino e da lontano, come l'obiettivo di una macchina fotografica.", "k": "Il cristallino è la lente che mette a fuoco."}, {"q": "Che cosa fa la pupilla quando c'è tanta luce?", "o": ["Diventa più piccola", "Diventa più grande", "Cambia colore"], "a": 0, "e": "Al buio si allarga per far entrare più luce. Prova davanti allo specchio accendendo la luce.", "k": "Con tanta luce la pupilla si restringe."}, {"q": "Come si chiama la parte dell'orecchio interno a forma di chiocciola?", "o": ["La cornea", "La coclea", "La laringe"], "a": 1, "e": "Dentro c'è un liquido e cellule speciali che mandano i suoni al cervello tramite un nervo.", "k": "La coclea, a forma di chiocciola, trasforma i suoni in segnali."}, {"q": "Che cosa porta le immagini dall'occhio al cervello?", "o": ["Il midollo spinale", "Le lacrime", "Il nervo ottico"], "a": 2, "e": "La retina raccoglie l'immagine, il nervo ottico la consegna al cervello, che la capisce.", "k": "Il nervo ottico porta le immagini al cervello."}, {"q": "Quanti pasti al giorno si consigliano di solito ai bambini?", "o": ["Cinque, con due spuntini", "Otto, tutti molto grandi", "Uno solo, abbondante"], "a": 0, "e": "Pasti più piccoli e regolari danno energia per tutto il giorno. Mai saltare la colazione!", "k": "Cinque pasti: colazione, spuntino, pranzo, merenda e cena."}, {"q": "Perché si lavano frutta e verdura prima di mangiarle?", "o": ["Per togliere terra, sporco e microbi", "Per renderle più dolci", "Per farle diventare più grandi"], "a": 0, "e": "Basta acqua corrente e un po' di strofinio con le mani, prima di mangiarle o sbucciarle.", "k": "Si lavano frutta e verdura per togliere sporco e microbi."}], "storia": [{"q": "Quale re fondò il grande impero persiano?", "o": ["Ciro il Grande", "Ramses II", "Hammurabi"], "a": 0, "e": "Ciro visse nel VI secolo a.C.; Ramses era un faraone egizio e Hammurabi un re di Babilonia.", "k": "Ciro il Grande fondò l'impero persiano."}, {"q": "Come si chiamavano i governatori delle province persiane?", "o": ["Faraoni", "Satrapi", "Consoli"], "a": 1, "e": "L'impero era enorme: il re lo divise in province e a ciascuna diede un satrapo che riscuoteva le tasse.", "k": "I satrapi governavano le province, chiamate satrapie."}, {"q": "Come si chiamava la lunga strada che attraversava l'impero persiano?", "o": ["La Strada Reale", "La Via della Seta", "La Via Appia"], "a": 0, "e": "Lungo la strada c'erano stazioni con cavalli freschi: così i messaggeri del re viaggiavano velocissimi.", "k": "La Strada Reale univa Sardi a Susa."}, {"q": "Quale passo difesero il re spartano Leonida e i suoi 300 uomini?", "o": ["Salamina", "Le Termopili", "Maratona"], "a": 1, "e": "Pochi Spartani resistettero a lungo contro l'enorme esercito persiano del re Serse, in un passaggio stretto tra monti e mare.", "k": "Leonida difese il passo delle Termopili nel 480 a.C."}, {"q": "In quale battaglia navale i Greci sconfissero la flotta persiana nel 480 a.C.?", "o": ["Termopili", "Olimpia", "Salamina"], "a": 2, "e": "Salamina è un'isola vicino ad Atene. Le navi greche, più agili, vinsero nello stretto braccio di mare.", "k": "A Salamina la flotta greca sconfisse i Persiani."}, {"q": "Chi era il padre di Alessandro Magno?", "o": ["Filippo II di Macedonia", "Leonida di Sparta", "Pericle di Atene"], "a": 0, "e": "Filippo rese forte la Macedonia; Alessandro divenne re a soli 20 anni, dopo la sua morte.", "k": "Il padre di Alessandro era Filippo II, re di Macedonia."}, {"q": "Come si chiamava il famoso cavallo di Alessandro Magno?", "o": ["Pegaso", "Bucefalo", "Incitato"], "a": 1, "e": "Da ragazzo Alessandro domò Bucefalo, che nessuno riusciva a cavalcare, girandolo verso il sole perché non vedesse la sua ombra.", "k": "Il cavallo di Alessandro si chiamava Bucefalo."}, {"q": "Quale grande impero sconfisse Alessandro Magno?", "o": ["L'impero romano", "L'impero persiano", "L'impero cinese"], "a": 1, "e": "Alessandro vinse il re persiano Dario III e conquistò i suoi territori, dall'Egitto fino all'India.", "k": "Alessandro sconfisse l'impero persiano."}, {"q": "Che cosa successe all'impero di Alessandro dopo la sua morte?", "o": ["Rimase unito per mille anni", "Passò tutto a Roma", "Fu diviso tra i suoi generali"], "a": 2, "e": "Nacquero i regni ellenistici: per esempio l'Egitto andò al generale Tolomeo.", "k": "Dopo Alessandro, l'impero fu diviso tra i suoi generali."}, {"q": "Che cosa si intende per «età ellenistica»?", "o": ["Il periodo in cui la cultura greca si diffuse in Oriente", "Il periodo delle piramidi egizie", "Il periodo dei primi re di Roma"], "a": 0, "e": "Elleni era il nome che i Greci davano a sé stessi. Dopo Alessandro, il greco si parlava dall'Egitto all'Asia.", "k": "Nell'età ellenistica la cultura greca si diffuse in Oriente."}, {"q": "Quale popolo italico abitava le montagne del Sannio e combatté a lungo contro Roma?", "o": ["I Sanniti", "I Persiani", "I Fenici"], "a": 0, "e": "Abitavano zone degli attuali Molise, Campania e Abruzzo e combatterono tre guerre contro Roma.", "k": "I Sanniti vivevano sui monti dell'Italia centro-meridionale."}, {"q": "Quale antico popolo ha dato il nome alla regione Veneto?", "o": ["I Sanniti", "I Veneti", "I Liguri"], "a": 1, "e": "Spesso il nome delle regioni viene dagli antichi popoli: Veneti per il Veneto, Umbri per l'Umbria, Liguri per la Liguria.", "k": "Gli antichi Veneti hanno dato il nome al Veneto."}, {"q": "Quale antico popolo ha dato il nome all'Umbria?", "o": ["Gli Umbri", "I Latini", "Gli Etruschi"], "a": 0, "e": "Gli Umbri vivevano a est del Tevere; a ovest del fiume vivevano invece gli Etruschi.", "k": "Gli Umbri hanno dato il nome all'Umbria."}, {"q": "Quale popolo venuto da nord, guidato da Brenno, saccheggiò Roma?", "o": ["Gli Egizi", "I Greci", "I Galli"], "a": 2, "e": "Secondo la leggenda, le oche sacre del Campidoglio svegliarono i difensori con il loro starnazzare.", "k": "I Galli di Brenno saccheggiarono Roma."}, {"q": "Secondo la tradizione, quante città formavano la lega degli Etruschi?", "o": ["100", "3", "12"], "a": 2, "e": "Si chiamava dodecapoli, cioè «dodici città». Ogni città era indipendente, ma si univano per feste e religione.", "k": "Secondo la tradizione, la lega etrusca riuniva 12 città."}, {"q": "In che anno nacque la Repubblica romana, secondo la tradizione?", "o": ["509 a.C.", "753 a.C.", "44 a.C."], "a": 0, "e": "Fu cacciato l'ultimo re, Tarquinio il Superbo. Il 753 a.C. è la fondazione di Roma.", "k": "Secondo la tradizione, la Repubblica nacque nel 509 a.C."}, {"q": "Per quanto tempo restava in carica un console?", "o": ["Un anno", "Tutta la vita", "Dieci anni"], "a": 0, "e": "Due consoli per un anno solo: così nessuno poteva diventare troppo potente, come un re.", "k": "I consoli restavano in carica un solo anno."}, {"q": "Come si chiamavano a Roma le persone comuni, come contadini e artigiani?", "o": ["Senatori", "Plebei", "Patrizi"], "a": 1, "e": "Da plebe viene la parola plebeo. I patrizi erano invece le famiglie nobili e ricche.", "k": "I plebei erano le persone comuni di Roma."}, {"q": "Chi difendeva i diritti dei plebei a Roma?", "o": ["I gladiatori", "I re di Roma", "I tribuni della plebe"], "a": 2, "e": "I tribuni potevano dire «veto», cioè «mi oppongo», per bloccare decisioni contro i plebei.", "k": "I tribuni della plebe difendevano i plebei."}, {"q": "Come si chiamavano le prime leggi scritte di Roma?", "o": ["Le leggi delle Dodici Tavole", "Il Codice di Hammurabi", "Le leggi delle Sette Colonne"], "a": 0, "e": "Scritte e mostrate a tutti nel foro, le leggi erano conosciute da tutti, anche dai plebei.", "k": "Le prime leggi scritte di Roma erano le Dodici Tavole."}, {"q": "Come si chiamava il capo scelto con pieni poteri in caso di grave pericolo?", "o": ["Il faraone", "Il dittatore", "Il tribuno"], "a": 1, "e": "Il dittatore romano aveva un tempo limitato: finito il pericolo, lasciava il potere.", "k": "Nei pericoli Roma sceglieva un dittatore per sei mesi al massimo."}, {"q": "Quale dittatore romano, dopo aver vinto, tornò subito ad arare i suoi campi?", "o": ["Annibale", "Cincinnato", "Spartaco"], "a": 1, "e": "Per i Romani Cincinnato era l'esempio del buon cittadino: serve la patria e non si tiene il potere.", "k": "Cincinnato lasciò il potere e tornò ai suoi campi."}, {"q": "Che cosa fecero i plebei per ottenere più diritti?", "o": ["Elessero un nuovo re", "Andarono a vivere in Grecia", "Uscirono da Roma, rifiutando di combattere"], "a": 2, "e": "Senza plebei Roma non aveva soldati né lavoratori, così i patrizi dovettero concedere loro dei diritti.", "k": "I plebei lasciarono Roma per ottenere diritti: la secessione."}, {"q": "Come si chiama il lungo periodo di pace iniziato con Augusto?", "o": ["La pax etrusca", "La pax romana", "La pax persiana"], "a": 1, "e": "Pax in latino vuol dire pace. Durò circa due secoli e favorì commerci e viaggi in tutto l'impero.", "k": "Con Augusto iniziò la pax romana."}, {"q": "Sotto quale imperatore avvenne il grande incendio di Roma del 64 d.C.?", "o": ["Augusto", "Costantino", "Nerone"], "a": 2, "e": "Dopo l'incendio Nerone fece costruire un enorme palazzo, la Domus Aurea, cioè «casa d'oro».", "k": "Il grande incendio di Roma avvenne sotto Nerone."}, {"q": "Come chiamavano i Romani i popoli che vivevano fuori dall'impero?", "o": ["Barbari", "Plebei", "Patrizi"], "a": 0, "e": "Barbaro voleva dire «chi balbetta»: i Greci e i Romani non capivano le loro lingue.", "k": "I Romani chiamavano barbari i popoli stranieri."}, {"q": "Quale popolo, guidato da Alarico, saccheggiò Roma nel 410 d.C.?", "o": ["Gli Etruschi", "I Cartaginesi", "I Visigoti"], "a": 2, "e": "Fu un fatto che spaventò tutto l'impero: da otto secoli Roma non veniva conquistata da nemici.", "k": "Nel 410 d.C. i Visigoti di Alarico saccheggiarono Roma."}, {"q": "Quale famiglia di imperatori fece costruire il Colosseo?", "o": ["I Flavi", "I Tarquini", "I Gracchi"], "a": 0, "e": "Il suo vero nome è Anfiteatro Flavio. Lo iniziò Vespasiano e lo inaugurò suo figlio Tito.", "k": "Il Colosseo fu costruito dagli imperatori Flavi."}, {"q": "Come si chiamavano i soldati della guardia dell'imperatore?", "o": ["Gli opliti", "I samurai", "I pretoriani"], "a": 2, "e": "Gli opliti erano soldati greci e i samurai guerrieri giapponesi; i pretoriani proteggevano l'imperatore a Roma.", "k": "I pretoriani erano la guardia dell'imperatore."}, {"q": "Che cosa successe all'Impero romano d'Oriente dopo il 476?", "o": ["Cadde lo stesso anno", "Diventò parte della Persia", "Durò ancora quasi mille anni"], "a": 2, "e": "Con capitale Costantinopoli, oggi Istanbul, durò quasi mille anni dopo la fine dell'Impero d'Occidente.", "k": "L'Impero d'Oriente durò fino al 1453."}]};
const FIX5 = {"sci-spazio": {"1uke6jd": {"e": "L'asse di Urano è inclinato di circa 98 gradi: invece di girare come una trottola, rotola intorno al Sole come una palla sul pavimento."}}, "geo": {"zd9gwd": {"e": "Nel 1957 sei Paesi firmarono a Roma i Trattati da cui nacque l'Europa unita: Italia, Francia, Germania Ovest, Belgio, Paesi Bassi e Lussemburgo."}}, "storia": {"1x1hmwd": {"e": "Il faraone era il re dell'antico Egitto e veniva considerato un dio in terra. Le piramidi più famose sono tombe di faraoni."}}, "tecno": {"1ilge4a": {"e": "Punti l'ago al centro e fai girare la matita: ecco un cerchio perfetto. La bussola invece trova il nord: non confonderli!"}}, "sci-energia": {"1m08a8l": {"e": "Premendo la corda la accorci: vibra più veloce e la nota diventa più acuta."}}, "sp-nuoto": {"1r5e335": {"e": "Prima braccia e respiro, poi la spinta delle gambe, poi lo scivolo. Filastrocca: «tira e respira, calcia e scivola»."}}, "ita": {"1d46d2j": {"e": "«Soqquadro» è l'unica parola di uso comune con due q: di solito si scrive «cq», come in acqua."}, "15fxx5x": {"ok": "Il nome preciso di una persona, un animale o un luogo", "e": "Il nome proprio indica proprio quello lì: Giulia, Roma, il fiume Po. Si scrive sempre con la maiuscola."}}};
